## Code Example
```c
typedef struct {
  int id;
  uint64_t runnable_ns;
  uint64_t blocked_ns;
  uint64_t cpu_quota_ns;
  uint64_t base_weight;
  // ... other fields
} container_t;

static inline uint64_t total_time(container_t *c){
  return c->runnable_ns + c->blocked_ns;
}

void update_weight(container_t *c){
  uint64_t t = total_time(c);
  if (t == 0) t = 1;
  c->weight = (uint64_t)(c->base_weight * c->runnable_ns / t);
}
``` 

